+#if defined(CONFIG_ESP_TIMER_TASK_STACK_SIZE)
+  if (std::strcmp(name, "esp_timer") == 0) {
+    return static_cast<std::uint32_t>(CONFIG_ESP_TIMER_TASK_STACK_SIZE);
+  }
+#endif
+#if defined(CONFIG_ESP_SYSTEM_EVENT_TASK_STACK_SIZE)
